#include <bits/stdc++.h>
using namespace std;
const int MOD = 998244353;
static bool inl(int n, int x, int a, int b, int i) {
    int r = n- b, d= n- x;
    if(i<=r && (i == 2 * a + 1|| i==2*a+2))return true;
    if(i>r && (i==2*d || i == 2*d+1))return true;
    if(i <= a + 1 && (i == 2*x - n || i == 2*x - n + 1))return true;
    return false;
}
static bool inr(int n, int x, int a, int b, int i) {
    int r = n-b, d = n-x;
    if (i >= r && (i == 2*d ||i == 2*d + 1)) return true;
    if (i >= a + 1 && i<=r&& (i == n - 2*b|| i == n - 2 *b-1))return true;
    if(i<=a && (i==2*x-n||i==2*x-n+1))return true;
    return false;
}
int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--) {
        int n;
        cin>>n;
        vector<vector<int>>I(n+1);
        for(int i=1;i<=n;i++) {
            int v;
            cin>>v;
            if(v>=1 && v<=n)I[v].push_back(i);
            else I[0].push_back(i);
        }
        bool bad = !I[0].empty();
        // for(int x = 1; x<=n&& !bad;x++) {
        //     if(I[x].size() > 4)bad = true;
        // }
        if(bad) {
            puts("0");
            continue;
        }
        vector<int>dp(n+2,0),ndp(n+2,0);
        dp[0]=1;
        for(int x = 1;x<n;x++) {
            fill(ndp.begin(),ndp.end(),0);
            const vector<int>& req = I[x];
            for(int a = 0;a<=x-1;a++) {
                if(!dp[a])continue;
                int b = x-1-a;
                bool okL = true, okR = true;
                for(int i:req){
                    if(okL &&!inl(n,x,a,b,i))okL = false;
                    if(okR && !inr(n,x,a,b,i))okR = false;
                    if(!okL && !okR)break;
                }
                if(okL){
                    ndp[a+1] += dp[a];
                    if(ndp[a+1] >=MOD)ndp[a+1]-=MOD;
                }
                if(okR) {
                    ndp[a] += dp[a];
                    if(ndp[a] >= MOD){
                        ndp[a] -= MOD;
                    }
                }}
                
                swap(dp,ndp);
            }
            long long ans = 0;
            for(int a=  0;a<=n-1;a++) {
                if(!dp[a])continue;
                bool ok = true;
                
                for(int i:I[n]) {
                    if(!((i==1&&a==0)||(i==n&&a==n-1))) {
                        ok = false;
                        break;
                    }
                }
                if(ok)ans+=dp[a];
            }
            cout<<ans%MOD<<'\n';        
            
        
    }
}
